"""Writes docs/CONVERSIONS.md from data/conversions.json: what changes, measured in the CAMELS simulations of four codes, when the definition of a quantity changes. Generated; do not edit docs/CONVERSIONS.md by hand.
Usage: python3 scripts/make-conversions-doc.py"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
D = json.loads((ROOT / "data" / "conversions.json").read_text())
CODES = ["IllustrisTNG", "SIMBA", "Astrid", "Swift-EAGLE"]
FIRST_THREE = CODES[:3]
BINS = [9.125, 9.625, 10.125, 10.625]
EDGE = lambda x: f"{x - 0.125:.2f} to {x + 0.125:.2f}"

SECTIONS = [
    ("Stellar mass: which stars are counted", "mass", [
        ("mass.total-to-rad2", "stars within twice the stellar half-mass radius, against all bound stars"),
        ("mass.total-to-radmax", "stars within the radius of maximum circular velocity, against all bound stars"),
        ("mass.total-to-rad1", "stars within the stellar half-mass radius: a built-in check, it must be log10(0.5) = -0.301 by definition")]),
    ("Star formation rate: which gas is counted", "sfr", [
        ("sfr.total-to-rad2", "SFR of gas within twice the stellar half-mass radius, against the SFR of all gas in the subhalo"),
        ("sfr.total-to-rad1", "within the stellar half-mass radius"),
        ("sfr.total-to-radmax", "within the radius of maximum circular velocity")]),
    ("Gas-phase metallicity: which gas is weighted", "gasz", [
        ("gasz.all-to-rad1", "gas within the stellar half-mass radius, against all gas in the subhalo (both mass-weighted)"),
        ("gasz.all-to-radmax", "gas within the radius of maximum circular velocity"),
        ("gasz.all-to-sfr", "star-forming gas only (mass-weighted)"),
        ("gasz.all-to-sfrweighted", "star-forming gas, weighted by SFR rather than mass")]),
    ("Stellar metallicity: which stars are counted", "starz", [
        ("starz.all-to-rad1", "stars within the stellar half-mass radius, against all bound stars"),
        ("starz.all-to-radmax", "stars within the radius of maximum circular velocity")]),
    ("Halo mass: M200crit against the total Subfind mass", "halo", [
        ("halo.m200crit-to-subhalo", "total mass of the central's Subfind subhalo, against the M200crit of its group (centrals only; the x axis is log10 M200crit)")]),
]


def cell(row):
    if not row:
        return "n/a"
    se = f" ± {row['seedSe']:.3f}" if row.get("seedSe") is not None else ""
    return f"{row['median']:+.2f} [{row['p16']:+.2f}, {row['p84']:+.2f}]{se}"


def table(key, snap="z0", bins=BINS, halo=False):
    xs = [11.125, 11.625, 12.125, 12.625] if halo else bins
    head = "| code | " + " | ".join((f"log M200c {x - 0.125:.2f} to {x + 0.125:.2f}" if halo else f"log M* {EDGE(x)}") for x in xs) + " |"
    L = [head, "|---|" + "---|" * len(xs)]
    for c in CODES:
        rows = {r["x"]: r for r in D["suites"][c].get(snap, {}).get("pairs", {}).get(key, [])}
        L.append(f"| {c} | " + " | ".join(cell(rows.get(x)) for x in xs) + " |")
    return L


def main():
    ng = D["suites"]["IllustrisTNG"]["z0"]["nSeeds"]
    vol = D["suites"]["IllustrisTNG"]["z0"]["gsmf"]["volumeMpc3"]
    se = D["suites"]["Swift-EAGLE"]["z0"]["pairs"]
    SE_SOURCE = D["suiteSources"]["Swift-EAGLE"]
    rad1 = [r["median"] for r in se["mass.total-to-rad1"]]
    SE_RAD1 = (min(rad1), max(rad1))
    SE_SFR = "; ".join(f"{r['median']:+.2f} at log M* {EDGE(r['x'])}, {r['n']} galaxies" for r in se["sfr.total-to-rad2"] if r["median"] < -0.02)
    L = ["# Measured conversions between definitions", "",
         "*Generated by `scripts/make-conversions-doc.py` from `data/conversions.json`; do not edit by hand.*", "",
         f"When two curves use different definitions (all bound stars or a 2 R_half aperture, SFR of all gas or of the disc, M200crit or the total Subfind mass), by how much does the number change? Instead of assuming, this page reports what the **public CAMELS catalogues** show: for each of four codes (IllustrisTNG, SIMBA, Astrid, Swift-EAGLE), {ng} fiducial-model boxes of 25 Mpc/h (total comoving volume {vol:,.0f} Mpc³ per code), read with `scripts/ingest_camels_conversions.py`. Each cell is the **median change in log10 of the quantity, with the 16th to 84th percentile of galaxies in square brackets and the standard error across the {ng} boxes after ±**. A negative number means the second definition gives a smaller value.", "",
         "## How to read and how not to use these numbers", "",
         "- These describe **these four codes at this resolution and box size**. The codes disagree with one another (see the tables), which is the point: there is no single aperture correction that fits every simulation, so the Explorer does not apply one. A reader who wants to correct a particular curve should measure it for the code that made it.",
         "- Only apertures that the catalogues provide are covered: all bound particles, twice the stellar half-mass radius, the stellar half-mass radius and the radius of maximum circular velocity. Fixed physical apertures (30 or 50 kpc), projected apertures, survey fibres and SED-fitted total masses are not in the catalogues and are not covered.",
         "- The catalogue documentation defines the aperture fields as sums over **all particles or cells within the radius**, and the total fields as the particles **bound to the subhalo** ([TNG data specification](https://www.tng-project.org/data/docs/specifications/)). The two can therefore differ for reasons other than the aperture (for example unbound stars inside the radius). We report the difference as measured.",
         "- The aperture SFR is documented as the total SFR \"restricted to cells within twice the stellar half mass radius\", so it should not exceed the total; in IllustrisTNG, SIMBA and Astrid the medians are slightly positive (below +0.02 dex in every bin published; checked by `scripts/test_camels_conversions.py`), which means the two fields are not an exact subset relation in those catalogues. We have not traced why; the effect is far smaller than the other numbers. Swift-EAGLE goes the other way (next point).",
         f"- **Swift-EAGLE is read from a different place, and probably made differently, from the other three.** Its group catalogues are not next to its snapshots (the `Sims` tree has particle snapshots of 1.2 to 1.8 GB each and no `groups_*.hdf5` files; its `extra_files` directory was not opened); they are in the `FOF_Subfind` tree of the CAMELS server (`{SE_SOURCE}`), for the same 27 fiducial boxes and the three snapshots at z = 0, 0.95 and 2.15. The catalogue directory holds a parameter file for an `arepo_subfind` run, which suggests that Subfind was run on the SWIFT snapshots by a separate post-processing step and that the gas is SPH particles, not Voronoi cells; that is inferred from file names and is not stated in the documentation we read. The array names are the same as for the other three codes; the mass unit is taken to be the same (10^10 solar masses per h: the parameter file gives `UnitMass_in_g` = 1.989e43, and the stellar mass in all subhaloes of one box at z = 0 is 0.0016 of the critical density, a plausible value, which is a rough check only). The stellar half-mass aperture comes out between {SE_RAD1[0]:+.3f} and {SE_RAD1[1]:+.3f} dex at z = 0 where the definition requires -0.301, which checks that field only. The CAMELS documentation says a bug had affected the Swift-EAGLE Subfind catalogues and that the public directories were then fixed; we did not test that. The SFR in the 2 R_half aperture is *below* the total in the high-mass bins ({SE_SFR}), unlike the first three codes; not traced. The CAMELS pages we read name no paper for this Swift-EAGLE variant and no licence for the data, so the model is described here only as the SWIFT code with the EAGLE subgrid model, which is how those pages list it. A search for further public codes with catalogues is written up in `docs/EXPANDING-COVERAGE.md`; the other CAMELS suites (Magneticum, Ramses, CROCODILE, Obsidian, Enzo) are listed there as private.",
         "- No resolution test has been run, so differences between the codes, especially at the low-mass end, could partly be resolution rather than physics.",
         "- Galaxies for which either quantity is exactly zero are left out of the median and counted in the zero-fraction column of `data/conversions.json`.", ""]
    for title, _, items in SECTIONS:
        L += [f"## {title}", ""]
        for key, desc in items:
            L += [f"**{desc}** (`{key}`, z = 0)", ""]
            L += table(key, halo=key.startswith("halo"))
            L.append("")
    L += ["## Redshift dependence of the aperture shift", "",
          "Stars within twice the stellar half-mass radius, against all bound stars, at log M* 10.00 to 10.25:", "", "| code | z = 0 | z = 0.95 | z = 2.15 |", "|---|---|---|---|"]
    for c in CODES:
        cells = []
        for snap in ("z0", "z0.95", "z2.15"):
            rows = {r["x"]: r for r in D["suites"][c].get(snap, {}).get("pairs", {}).get("mass.total-to-rad2", [])}
            cells.append(cell(rows.get(10.125)))
        L.append(f"| {c} | " + " | ".join(cells) + " |")
    L += ["", "## What it does to a mass function", "",
          "The change in a stellar mass function is not the median shift, because galaxies change mass by different amounts and the function is steep. We therefore rebuilt the mass function of each code from each mass definition and measured the **horizontal shift in log10 M\\* at fixed cumulative number density** (the mass above which a given number of galaxies per Mpc³ lie), with the standard error across boxes.", "",
          "| code | conversion | n(>M) = 10^-2 | 10^-2.5 | 10^-3 | 10^-3.5 |", "|---|---|---|---|---|---|"]
    for c in CODES:
        sh = D["suites"][c]["z0"]["gsmfShiftAtFixedNumberDensity"]
        for conv, label in (("total-to-rad2", "2 R_half aperture"), ("total-to-radmax", "R(V_max) aperture")):
            cells = []
            for nd in ("-2", "-2.5", "-3", "-3.5"):
                v = sh[conv][nd]
                cells.append("n/a" if v["shiftDex"] is None else f"{v['shiftDex']:+.2f}" + (f" ± {v['seedSe']:.3f}" if v["seedSe"] is not None else ""))
            L.append(f"| {c} | {label} | " + " | ".join(cells) + " |")
    L += ["", "Densities are in Mpc⁻³; the volume is small, so the highest-mass column (10^-3.5) rests on few galaxies per box.", "",
          "## Where the numbers come from", "",
          f"`data/ensembles/camels-conversions.json` holds the per-box medians and counts and the pooled histograms; the SHA-256 of the catalogue arrays read is in `data/conversions.json` (`arraysSha256`, per code and snapshot). Retrieved {D['retrieved']} (Swift-EAGLE: {D['retrievedBySuite']['Swift-EAGLE']}). Source: {D['source']}. Files read, with {{name}} the box (CV_0 to CV_26) and {{snap}} the snapshot (090, 062, 042), and the date each code was read: " + "; ".join(f"{c}: `{D['suiteSources'][c]}`, {D['retrievedBySuite'][c]}" for c in CODES) + ".", ""]
    (ROOT / "docs" / "CONVERSIONS.md").write_text("\n".join(L))
    print("wrote docs/CONVERSIONS.md")


if __name__ == "__main__":
    main()
